        if (paymentMethods.isEmpty()) {
            Toast.makeText(this, R.string.select_payment_method_required, Toast.LENGTH_SHORT).show();
            valid = false;
        }

        if (!valid) return;

        Customer c = new Customer(customerId, business, contact, address,
                phone.isEmpty() ? null : phone,
                br.isEmpty() ? null : br,
                idNum.isEmpty() ? null : idNum,
                paymentMethods);

        new Thread(() -> {
